fn solve(input: Vec<(i8, i8)>) -> Vec<i8> {
    let mut result = Vec::with_capacity(input.len());
    for (a, b) in input {
        let delta = b - a;
        let moves = if delta == 0 {
            0
        } else if delta > 0 {
            // Need to increase by delta using odd increments
            let d = delta; // delta is positive here
            if d % 2 != 0 { 1 } else { 2 }
        } else {
            // delta < 0: need to decrease by -delta using even decrements
            let d = (-delta) as i8; // positive
            if d % 2 == 0 { 1 } else { 2 }
        };
        result.push(moves);
    }
    result
}

